create table clientes (id int primary key, nombre text not null, zona text not null);
create table choferes (id int primary key, nombre text not null, supervisor_id int references choferes(id));
create table envios (
  id         int primary key,
  cliente_id int not null references clientes(id),
  chofer_id  int references choferes(id),
  bultos     int not null,
  estado     text not null
);
create table incidentes (id int primary key, envio_id int not null references envios(id), tipo text not null);
